"text":"Клетка 6","bind":"v6","style":{"align":"center"}}]},{"type":"column","children":[{"type":"button","text":"7","action":"open7","enabledBind":"active","semantics":{"label":"Открыть клетку 7"}},{"type":"text","text":"Клетка 7","bind":"v7","style":{"align":"center"}}]},{"type":"column","children":[{"type":"button","text":"8","action":"open8","enabledBind":"active","semantics":{"label":"Открыть клетку 8"}},{"type":"text","text":"Клетка 8","bind":"v8","style":{"align":"center"}}]},{"type":"column","children":[{"type":"button","text":"9","action":"open9","enabledBind":"active","semantics":{"label":"Открыть клетку 9"}},{"type":"text","text":"Клетка 9","bind":"v9","style":{"align":"center"}}]}]},{"type":"row","children":[{"type":"button","text":"Заново","action":"reset","variant":"filled"}]}]},"behaviorBindings":{"c1":[2,0,0],"c2":[2,1,0],"c3":[2,2,0],"c5":[2,4,0],"c8":[2,7,0],"score":[0],"status":[1],"reset":[3,0]},"source":"const ev = input.event;
const s = Object.assign({}, input.state);
const STAR = {2:true,5:true,8:true};
function resetGame(){ s.score = 0; s.active = true; for (let i = 1; i <= 9; i++) { s['v' + i] = '?'; } s.status = 'Новая игра. Найдите три звезды!'; }
if (ev.type === 'action') {
  const id = ev.actionId;
  if (id === 'reset') {
    resetGame();
  } else if (typeof id === 'string' && id.indexOf('open') === 0) {
    const n = Number(id.slice(4));
    const key = 'v' + n;
    if (s.active && n >= 1 && n <= 9 && s[key] === '?') {
      if (STAR[n]) {
        s[key] = '★';
        s.score = Math.min(3, s.score + 1);
        if (s.score >= 3) {
          s.status = 'Победа! Все три звезды найдены.';
          s.active = false;
        } else {
          s.status = 'Звезда! Клетка ' + n + '. Очков: ' + s.score;
        }
      } else {
        s[key] = 'пусто';
        s.status = 'Клетка ' + n + ' пуста. Очков: ' + s.score;
      }
    }
  }
}
return {state: s};"}
